import {ventilationReminder} from './ventilation-reminder.js';
// One renderer and one encounter field keep Trauma and Cardiac arrest in sync.
export function traumaArrestPanel(fields,icon,source){return `<details class="trauma-arrest-panel" ${fields['trauma-arrest-open']?'open':''}><summary><span class="trauma-arrest-icon">${icon('skull')}</span><span><b>Trauma arrest</b></span><span class="trauma-arrest-expand" aria-hidden="true">+</span></summary><div class="trauma-arrest-content">
  <div class="trauma-arrest-heading">${source('TRAUMATIC ARREST · S509',148)}</div>
  <div class="trauma-arrest-focus"><strong>Reversible causes take priority over chest compressions.</strong><p><b>Chest compressions alone cannot reverse traumatic arrest or sustain perfusion without correction of the underlying cause.</b></p><p>Hemorrhage / hypovolemia · hypoxia · tension pneumothorax · tamponade.</p><p>CPR alongside treatment per S509. Do not delay correction of reversible causes.</p></div>
  <section class="trauma-arrest-prep"><h3>Prepare</h3><p><b>Turn main O2 AND cabin power on. Turn up the heat.</b></p><p>Suction / BVM · hemorrhage kit · bilateral decompression kit · IV / IO + saline / pressure bag · monitor / pads.</p></section>
  <div class="trauma-arrest-actions">
    <section data-trauma-priority="bleeding"><span>01</span><div><h3>Stop external bleeding</h3>${source('HEMORRHAGE · T710',199)}</div></section>
    <section data-trauma-priority="chest"><span>02</span><div><h3>Decompress both sides · ALS</h3><p>Blunt trauma / penetrating torso injury → bilateral needle decompression per T701. Persistent arrest → consider repeat decompression.</p></div></section>
    <section data-trauma-priority="oxygen"><span>03</span><div><h3>Oxygenate + ventilate</h3>${ventilationReminder()}${source('AIRWAY · T705',189)}</div></section>
    <section data-trauma-priority="volume"><span>04</span><div><h3>Restore circulating volume</h3><p>IV / IO · adult NS 1 L; pediatric NS 20 mL/kg · open flow / IO pressure bag.</p></div></section>
  </div>
  <section class="trauma-arrest-transport"><h3>Rhythm, destination & medical control</h3><div class="trauma-arrest-rhythms"><p><b>VF / pulseless VT:</b> shock per C300 / P601, fluids, consider repeat decompression, nearest trauma center.</p><p><b>PEA &gt;40 bpm:</b> fluids, consider repeat decompression, nearest trauma center.</p><p><b>Asystole / PEA &lt;40 bpm:</b> contact Medical Control about termination.</p></div><p><b>Expedite:</b> EMS-witnessed penetrating arrest → nearest trauma center; ROSC → immediate transport. Under 18: pediatric trauma center may be used.</p><p><b>Pregnancy exception:</b> known pregnancy &gt;24 weeks or fundus at / above the umbilicus → nearest ED for possible resuscitative delivery.</p><p><b>Trauma does not explain arrest:</b> medical-arrest pathway (SB204).</p></section>
  <aside class="trauma-arrest-exclusions"><b>Traumatic / hypovolemic arrest: S509 does not recommend routine epi / atropine. TXA is not beneficial in traumatic arrest. Do not initiate post-ROSC cooling.</b></aside>
  <div class="trauma-arrest-links">${source('S509 · FULL PROTOCOL & TRANSPORT',148)}${source('S509 · NOTES & TERMINATION',149)}<a class="source" href="https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/special-circumstances-guidelines" target="_blank" rel="noopener noreferrer">REVERSIBLE-CAUSE PRIORITY · RCUK 2025</a></div>
</div></details>`;}
export function rememberTraumaArrest(fields){const panel=document.querySelector('.trauma-arrest-panel');if(panel)fields['trauma-arrest-open']=panel.open;}
export function bindTraumaArrest(getState,save){document.addEventListener('toggle',e=>{if(e.target.matches('.trauma-arrest-panel')){getState().fields['trauma-arrest-open']=e.target.open;save();}},true);}
